6	-- Security invoker on purpose: ResourceAccess's own select policy still applies, and callers can already read their own grants.
7	-- Unlike my_accessible_resources(), the planner can inline a view, so a policy can check one row through the ResourceAccess index without building all the caller's grants.
8	CREATE OR REPLACE VIEW public.my_resource_grants WITH (security_invoker) AS
9	SELECT ra.space_id, ra.source_local_id
10	FROM public."ResourceAccess" AS ra
11	WHERE ra.account_uid = any((SELECT array_agg(my.uid) FROM public.my_user_accounts() AS my (uid))::uuid[]);
